#!/usr/bin/env bash
# Verify the install is coherent: links correct, generated files current,
# registry entries present, no placeholder left behind.
set -uo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# shellcheck source=lib/platform.sh
source "$ROOT_DIR/scripts/lib/platform.sh"
# shellcheck source=lib/targets.sh
source "$ROOT_DIR/scripts/lib/targets.sh"
fail=0
ok()   { echo "ok    $*"; }
warn() { echo "warn  $*"; }
bad()  { echo "FAIL  $*"; fail=1; }
ok "platform: $OS ($LINK_MODE mode)"

# 1. Generated files current
# Rebuild with the path recorded in dist/, so the comparison does not depend on
# the HOME the original build ran under.
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
cp -R "$ROOT_DIR" "$TMP/repo"
RECORDED="$(sed -n 's/^Central context: `\(.*\)`$/\1/p' "$ROOT_DIR/dist/agents.md" 2>/dev/null | head -1)"
( cd "$TMP/repo" && rm -rf dist AGENTS.md && CENTRAL_DIR="$RECORDED" ./scripts/build.sh >/dev/null )
if [[ -f "$ROOT_DIR/dist/agents.md" ]]; then
  for f in dist/agents.md dist/opencode/AGENTS.md dist/claude/CLAUDE.md \
           dist/codex/AGENTS.md dist/gemini/GEMINI.md dist/cursor/rules/agent-policy.mdc; do
    if cmp -s "$TMP/repo/$f" "$ROOT_DIR/$f"; then ok "current $f"; else bad "stale   $f (run scripts/build.sh)"; fi
  done
else
  warn "not built yet (run scripts/build.sh)"
fi
# Project-slot check applies to repositories that carry their own context.
# The published template is the exception: its root AGENTS.md *is* the contract.
if [[ -d "$ROOT_DIR/.ai" ]]; then
  if [[ -f "$ROOT_DIR/AGENTS.md" ]] && ! grep -q "GENERATED by scripts/build.sh" "$ROOT_DIR/AGENTS.md"; then
    ok "project AGENTS.md is repo-local"
  else
    bad "project AGENTS.md missing or generated (it must be repo-local, not the contract)"
  fi
elif [[ -f "$ROOT_DIR/AGENTS.md" ]] && grep -q "GENERATED by scripts/build.sh" "$ROOT_DIR/AGENTS.md"; then
  ok "template AGENTS.md is the generated contract"
else
  warn "no .ai/ context and no contract at the root"
fi

# 2. Installed targets (only meaningful for the repository that installed them)
if [[ -d "$ROOT_DIR/.ai" ]]; then
  for row in "${TARGETS[@]}"; do
    IFS='|' read -r tool src dest <<<"$row"
    if [[ ! -e "$dest" && ! -L "$dest" ]]; then
      bad "missing $tool  $dest"
    elif [[ "$LINK_MODE" == "symlink" ]]; then
      if [[ -L "$dest" ]]; then
        ok "link    $tool -> $dest"
      else
        warn "regular file $tool  $dest (not managed by install.sh)"
      fi
    else
      # Copy mode: the marker and an exact match are the only proof.
      if ! is_managed "$dest"; then
        warn "foreign file $tool  $dest (not installed by this repository)"
      elif cmp -s "$ROOT_DIR/$src" "$dest"; then
        ok "copy    $tool -> $dest"
      else
        bad "stale   copy $tool  $dest (re-run install.sh --apply)"
      fi
    fi
  done
else
  warn "template repository: global targets belong to the dev repository"
fi

# 3. Registry integrity
missing=0
while read -r p; do
  [[ -z "$p" ]] && continue
  [[ -f "$ROOT_DIR/$p" ]] || { bad "registry path missing: $p"; missing=1; }
done < <(grep -E '^\s+- path: ' "$ROOT_DIR/registry.yaml" | awk '{print $3}')
[[ "$missing" == 0 ]] && ok "registry paths resolve"

# 4. No unresolved placeholder in the personal build
#    dist/public/AGENTS.md is expected to keep the placeholder: it is the template.
if grep -rn "__CENTRAL_DIR__" \
     "$ROOT_DIR/AGENTS.md" \
     "$ROOT_DIR/dist/agents.md" \
     "$ROOT_DIR/dist/opencode" "$ROOT_DIR/dist/claude" "$ROOT_DIR/dist/codex" \
     "$ROOT_DIR/dist/gemini" "$ROOT_DIR/dist/cursor" >/dev/null 2>&1; then
  bad "unresolved __CENTRAL_DIR__ in personal output"
else
  ok "no placeholders in personal output"
fi

echo
[[ "$fail" == 0 ]] && echo "doctor: clean" || { echo "doctor: problems found"; exit 1; }
